-- 169: Original BrillaPrep WASSCE BrillaPrep transitional Building Construction beta content blueprint questions, part 6.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_169_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_169_guard;
INSERT INTO _migration_169_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_026' AND NOT (q.topic_id IS 'topic_was_building_b003_6' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the function of a ridge board in a traditional cut roof?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Carry all roof loads without support from rafters","B. Provide alignment and a fixing line for opposing rafters","C. Collect rainwater at the eaves","D. Tie the wall plates directly to the foundation"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The ridge board helps locate and connect rafter heads; it is not normally designed as the primary spanning structural member. Therefore the correct answer is B: Provide alignment and a fixing line for opposing rafters.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_026' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_169_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_027' AND NOT (q.topic_id IS 'topic_was_building_b003_6' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are ceiling ties or tie beams used in a pitched roof?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase rainwater penetration at the eaves","B. Support roof tiles without battens","C. Resist outward spread at the feet of opposing rafters","D. Replace the ridge connection completely"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The tie completes a triangle and carries tension that restrains rafters from pushing the supporting walls outward. Therefore the correct answer is C: Resist outward spread at the feet of opposing rafters.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_027' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_169_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_028' AND NOT (q.topic_id IS 'topic_was_building_b003_6' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of flashing where a roof meets a masonry wall?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Ventilate the wall cavity into the room","B. Transfer foundation loads into the roof","C. Hold ceiling boards between joists","D. Form a durable weatherproof junction that sheds water"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Properly lapped flashing bridges the junction and directs rain onto the roof covering rather than allowing entry through the change in material. Therefore the correct answer is D: Form a durable weatherproof junction that sheds water.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_028' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_169_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_029' AND NOT (q.topic_id IS 'topic_was_building_b003_6' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must roof tiles or sheets have the specified side and end laps?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Prevent wind-driven rain entering through joints","B. Reduce the roof pitch to zero","C. Transfer all roof loads to the gutters","D. Eliminate the need for structural supports"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Correct laps use gravity and capillary breaks to maintain drainage continuity, especially when wind pushes rain across the covering. Therefore the correct answer is A: Prevent wind-driven rain entering through joints.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_029' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_169_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_030' AND NOT (q.topic_id IS 'topic_was_building_b003_6' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main function of roof gutters and downpipes?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Store permanent water loads at the eaves","B. Collect runoff and discharge it safely away from the building","C. Ventilate the roof space through standing water","D. Support the lower ends of all rafters"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Controlled rainwater disposal limits erosion, staining, splashback and saturation near walls and foundations. Therefore the correct answer is B: Collect runoff and discharge it safely away from the building.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_030' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
